-- PNJ d'ambiance dans toutes les capitales, Shattrath et Dalaran (section 6.5 ; objectif de l'utilisateur du
-- 28/10/2026 : à terme tout le monde). ambiance.cpp lit les lieux animés dans solazeroth_ambiance_lieux.
USE acore_world;

-- Camp des apparences : 0 Alliance (les 742 de la migration 042), 1 Horde.
ALTER TABLE solazeroth_ambiance_apparences ADD COLUMN camp TINYINT UNSIGNED NOT NULL DEFAULT 0;

-- Apparences de joueurs de la Horde : modèles habillés (CreatureDisplayInfoExtra) d'adultes orcs, morts-vivants, taurens,
-- trolls et elfes de sang, tirés des PNJ humanoïdes d'Orgrimmar, des Pitons-du-Tonnerre, de Fossoyeuse et de
-- Lune-d'Argent (sans gardes, Kor'kron, enfants ni déclencheurs) : 762 modèles.

-- Lieux animés. camp : 0 Alliance, 1 Horde, 2 les deux. densite multiplie les nombres de mod_solazeroth.conf
-- (Hurlevent = 1, réglé en jeu le 28/10/2026) selon la taille de la ville.
CREATE TABLE solazeroth_ambiance_lieux (
    carte SMALLINT UNSIGNED NOT NULL,
    zone INT UNSIGNED NOT NULL,
    nom VARCHAR(64) NOT NULL,
    camp TINYINT UNSIGNED NOT NULL,
    densite FLOAT NOT NULL DEFAULT 1,
    PRIMARY KEY (carte, zone)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

